/* decimal digits of v by subtracting powers of ten: the eZ80 divides 32-bit numbers in software, a dozen of those per
 * label cost a millisecond each; returns the length, at least "0" */
static int u2s(char *out, unsigned long v) {
    static const unsigned long PT10[10] = { 1000000000UL, 100000000UL, 10000000UL, 1000000UL, 100000UL, 10000UL, 1000UL, 100UL, 10UL, 1UL };
    int n = 0;
    for (int i = 0; i < 10; i++) {
        char d = '0'; unsigned long p = PT10[i];
        while (v >= p) { v -= p; d++; }
        if (d != '0' || n || i == 9) out[n++] = d;
    }
    out[n] = 0;
    return n;
}
/* ip with thousands commas, then `dec` decimals of fp */
static char *digits(char *o, long ip, long fp, uint8_t dec) {
    char t[12]; int n = u2s(t, ip < 0 ? 0 : (unsigned long)ip);
    for (int i = 0; i < n; i++) { *o++ = t[i]; if ((n - 1 - i) % 3 == 0 && i != n - 1) *o++ = ','; }
    if (dec) {
        int m = u2s(t, fp < 0 ? 0 : (unsigned long)fp);
        *o++ = '.';
        for (int i = m; i < dec; i++) *o++ = '0';
        for (int i = 0; i < m; i++) *o++ = t[i];
    }
    *o = 0;
    return o;
}
/* fmtMoney: "+$1,234" / "-$15"; a flat zero reads "$0" */
static char *money_to(char *o, float d, bool cents) {
    bool neg = d < 0; if (neg) d = -d;
    long dollars = (long)d, c = (long)((d - (float)dollars) * 100.0f + 0.5f);
    if (c >= 100) { dollars++; c -= 100; }
    if (!cents && c >= 50) dollars++;
    if (!cents && dollars == 0) { *o++ = '$'; *o++ = '0'; *o = 0; return o; }
    *o++ = neg ? '-' : '+'; *o++ = '$';
    return cents ? digits(o, dollars, c, 2) : digits(o, dollars, 0, 0);
}
static const char *money(float d, bool cents) { money_to(buf, d, cents); return buf; }
/* a raw price (price * 10^dec, an integer) with `show` decimals */
static const char *price_raw(long raw, uint8_t show) {
    static const long HALF[7] = { 0, 5, 50, 500, 5000, 50000, 500000 };
    int drop = W.dec - show;
    char t[12]; int n = u2s(t, (unsigned long)(raw + HALF[drop] < 0 ? 0 : raw + HALF[drop]));
    n -= drop; if (n < 1) { t[0] = '0'; n = 1; }
    t[n] = 0;
    /* t holds the number in units of 10^-show: split its last `show` digits off as the fraction */
    char ip[12], *o = buf; int il = n - show;
    if (il < 1) { ip[0] = '0'; il = 1; ip[1] = 0; } else { memcpy(ip, t, il); ip[il] = 0; }
    for (int i = 0; i < il; i++) { *o++ = ip[i]; if ((il - 1 - i) % 3 == 0 && i != il - 1) *o++ = ','; }
    if (show) {
        *o++ = '.';
        int fl = n - (n - show < 0 ? 0 : n - show);
        for (int i = fl; i < show; i++) *o++ = '0';
        for (int i = n - fl; i < n; i++) *o++ = t[i];
    }
    *o = 0;
    return buf;
}
static long raw_of(int v) { return (long)(rawp(v) + 0.5f); }
