    int fr, fg, fbb, br, bgg, bb; rgb_of(f, &fr, &fg, &fbb); rgb_of(k, &br, &bgg, &bb);
    gfx_palette[160 + 2 * best] = gfx_RGBTo1555(br + (fr - br) / 3, bgg + (fg - bgg) / 3, bb + (fbb - bb) / 3);
    gfx_palette[161 + 2 * best] = gfx_RGBTo1555(br + 2 * (fr - br) / 3, bgg + 2 * (fg - bgg) / 3, bb + 2 * (fbb - bb) / 3);
