static float ridePnl(int price) { return pos.notional * (rawp(price) / pos.entryRaw - 1.0f) * pos.dir - pos.fee; }

static void camera(float dt, bool snap) {
    int first = kf - VIS; if (first < 0) first = 0;
    int lo = fl, hi = fh;
    for (int i = first; i < kf; i++) { int a = BL(i), b = BH(i); if (a < lo) lo = a; if (b > hi) hi = b; }
    /* an open ride's entry stays in view, unless that would more than double the scale: at 190 px tall the candles
     * were crushed into a strip after a 2% move (the phone's plot is 700 px) */
    if (pos.on) {
        int span = hi - lo, l2 = pos.entry < lo ? pos.entry : lo, h2 = pos.entry > hi ? pos.entry : hi;
        if (h2 - l2 <= span * 2) { lo = l2; hi = h2; }
    }
    int pad = (hi - lo) / 12 + 1; lo -= pad; hi += pad;
    if (snap) { camLoF = (float)lo; camHiF = (float)hi; }
    else {
        float a = 1.0f - exp_f(-dt * 6.0f);
        camLoF = (float)lo < camLoF ? (float)lo : camLoF + ((float)lo - camLoF) * a;
        camHiF = (float)hi > camHiF ? (float)hi : camHiF + ((float)hi - camHiF) * a;
    }
    camLo = (long)camLoF; camHi = (long)camHiF + 1;
    camRange = camHi - camLo; if (camRange < 2) camRange = 2;
    camSc = ((long)(pb - PT) << 16) / camRange;
    camHiI = (int)camHi; camLimLo = (int)(-camRange * 2); camLimHi = (int)(camRange * 3); camScI = (int)(camSc);
}

/* niceStep in raw units (1-2-5), at least 1, with the decimals its step needs */
static long nice_step(long raw, uint8_t *show) {
    long p = 1; int n = 0;
    if (raw < 1) raw = 1;
    while (p * 10 <= raw) { p *= 10; n++; }
    long m10 = raw * 10 / p, s = (m10 < 15 ? 1 : m10 < 30 ? 2 : m10 < 70 ? 5 : 10) * p;
    if (m10 >= 70) n++;
    int sh = (int)W.dec - n; if (sh < 0) sh = 0; if (sh > W.dec) sh = W.dec;
    *show = (uint8_t)sh;
    return s;
}
static long gridStep; static uint8_t gridShow; static long gridLoRaw, gridHiRaw;
static void grid_prep(void) {
    gridLoRaw = raw_of((int)camLo); gridHiRaw = raw_of((int)camHi);
    gridStep = nice_step((gridHiRaw - gridLoRaw) / 6, &gridShow);   /* the app: niceStep((hi - lo) / 6) */
}


