static uint8_t preset;
/* the big work arrays: static on the calculator; on the T-Deck they come from the heap (its static RAM is nearly
 * full with the firmware's own) */
#ifdef SR_TDECK
#define BIG(type, name, n) static type *name; if (!name) name = (type *)calloc(n, sizeof(type))
static int (*is)[MAXB];           /* overlay series, price units */
#else
#define BIG(type, name, n) static type name[n]
static int is[5][MAXB];           /* overlay series, price units */
#endif
static int ps[3][MAXB];           /* pane series: RSI 0..100; MACD line, signal, histogram in price units */
static int8_t sdir[MAXB];         /* ribbon e8 > e55, bands squeeze, supertrend direction (-1 up, as Pine) */
typedef struct { int start, conf, brk, lvl; bool res; } Lvl;
#define MAXL 28
static Lvl lv[MAXL]; static uint8_t nlv;
static int evDone;                /* the last bar whose BUY/SELL/BREAK has popped */

static float sqrt_f(float x) {
    if (x <= 0) return 0;
    float r = 1; while (r * r * 16 < x) r *= 4; /* a starting guess near the root */
    for (int i = 0; i < 8; i++) r = 0.5f * (r + x / r);
    return r;
}

static void ind_compute(void) {
    BIG(float, c, MAXB);
    int n = nbars < MAXB ? nbars : MAXB;
    for (int i = 0; i < n; i++) c[i] = (float)BC(i);
    nlv = 0; evDone = lead - 1;
    if (preset == 0) {
        static const uint8_t L[5] = { 8, 13, 21, 34, 55 };
        for (int j = 0; j < 5; j++) { float a = 2.0f / (L[j] + 1), e = c[0]; for (int i = 0; i < n; i++) { e += a * (c[i] - e); is[j][i] = (int)e; } }
        for (int i = 0; i < n; i++) sdir[i] = is[0][i] > is[4][i] ? 1 : -1;
        float ag = 0, al = 0;
        for (int i = 1; i < n; i++) {
            float d = c[i] - c[i - 1], g = d > 0 ? d : 0, l = d < 0 ? -d : 0;
            if (i <= 14) { ag += g / 14; al += l / 14; } else { ag += (g - ag) / 14; al += (l - al) / 14; }
            ps[0][i] = al <= 0 ? 100 : (int)(100 - 100 / (1 + ag / al));
        }
        ps[0][0] = 50;
    } else if (preset == 1) {
        float e12 = c[0], e26 = c[0], sg = 0;
        BIG(float, bw, MAXB);
        for (int i = 0; i < n; i++) {
            e12 += (2.0f / 13) * (c[i] - e12); e26 += (2.0f / 27) * (c[i] - e26);
            float m = e12 - e26; if (i == 0) sg = m; sg += (2.0f / 10) * (m - sg);
            ps[0][i] = (int)m; ps[1][i] = (int)sg; ps[2][i] = (int)(m - sg);
            int a = i >= 19 ? i - 19 : 0; float s = 0; for (int j = a; j <= i; j++) s += c[j];
            float mean = s / (i - a + 1), v = 0; for (int j = a; j <= i; j++) v += (c[j] - mean) * (c[j] - mean);
            float sd = sqrt_f(v / (i - a + 1));
            is[0][i] = (int)mean; is[1][i] = (int)(mean + 2 * sd); is[2][i] = (int)(mean - 2 * sd);
            bw[i] = mean > 0 ? 4 * sd / mean : 0;
            float lo = bw[i]; for (int j = i >= 59 ? i - 59 : 0; j < i; j++) if (bw[j] < lo) lo = bw[j];
            sdir[i] = i >= 59 && bw[i] <= lo ? 1 : 0;
        }
    } else if (preset == 2) {
        float atr = 0, up = 0, dn = 0, st = 0; int dir = 1;
        for (int i = 0; i < n; i++) {
            float h = (float)BH(i), l = (float)BL(i), tr = h - l;
            if (i) { float a = h - c[i - 1], b = c[i - 1] - l; if (a < 0) a = -a; if (b < 0) b = -b; if (a > tr) tr = a; if (b > tr) tr = b; }
            atr = i < 10 ? (atr * i + tr) / (i + 1) : atr + (tr - atr) / 10;
            float m = (h + l) / 2, u = m - 3 * atr, d = m + 3 * atr;
            if (i) { if (c[i - 1] > up && u < up) u = up; if (c[i - 1] < dn && d > dn) d = dn; }
            int nd = !i ? 1 : (st == dn ? (c[i] > d ? -1 : 1) : (c[i] < u ? 1 : -1));
            up = u; dn = d; dir = nd; st = dir < 0 ? up : dn;
            is[0][i] = (int)st; sdir[i] = (int8_t)dir;
        }
    } else {
        float pv = 0, vv = 0, p2 = 0;
        for (int i = 0; i < n; i++) {
            if (!i || (W.start + (uint32_t)i * 300) % 86400 == 0) { pv = vv = p2 = 0; }
            float p = ((float)BH(i) + (float)BL(i) + c[i]) / 3, v = (float)RD16(W.vol, i) + 1;
            pv += p * v; vv += v; p2 += p * p * v;
            float vw = pv / vv, var = p2 / vv - vw * vw, sd = sqrt_f(var);
            is[0][i] = (int)vw; is[1][i] = (int)(vw + sd); is[2][i] = (int)(vw - sd);
        }
        for (int i = 8; i + 8 < n && nlv < MAXL; i++) {
            int h = BH(i), l = BL(i); bool ph = true, pl = true;
            for (int j = i - 8; j <= i + 8 && (ph || pl); j++) {
                if (j == i) continue;
                if (BH(j) > h || (j < i && BH(j) == h)) ph = false;
                if (BL(j) < l || (j < i && BL(j) == l)) pl = false;
            }
            for (int t = 0; t < 2 && nlv < MAXL; t++) {
                if (!(t ? pl : ph)) continue;
                Lvl *L = &lv[nlv++];
                L->start = i; L->conf = i + 8; L->lvl = t ? l : h; L->res = !t; L->brk = -1;
                for (int b = i + 9; b < n; b++) {
                    int cb = BC(b), cp = BC(b - 1);
                    if (L->res ? (cb > L->lvl && cp <= L->lvl) : (cb < L->lvl && cp >= L->lvl)) { L->brk = b; break; }
                }
            }
        }
    }
    pb = PB; /* overlays only: at 320 x 240 a pane squeezed the chart to a strip */
}

/* ---- bots: any of the indicators trades the round for you. Each is a position per bar (+1 long, -1 short, 0 flat)
 * from the same series the chart draws; the round holds and slides for it, so its rides look like yours. ---------- */
#define NBOT 7
static const char *const BOT_NAME[NBOT] = { "EMA RIBBON", "RSI 30/70", "MACD", "BOLLINGER", "SUPERTREND", "VWAP", "S/R BREAKOUT" };
static const char *const BOT_DESC[NBOT] = { "LONG WHILE THE 8 EMA IS OVER THE 55, SHORT UNDER", "BUYS A CROSS UP THROUGH 30, SELLS A CROSS DOWN THROUGH 70",
    "LONG OVER THE SIGNAL LINE, SHORT UNDER", "BUYS UNDER THE LOW BAND, SELLS OVER THE HIGH, OUT AT THE MEAN",
    "LONG WHEN IT FLIPS UP, SHORT WHEN IT FLIPS DOWN", "LONG OVER VWAP, SHORT UNDER", "LONG A RESISTANCE BREAK, SHORT A SUPPORT BREAK" };
static const uint8_t BOT_PRESET[NBOT] = { 0, 0, 1, 1, 2, 3, 3 };
static int8_t botI = -1;           /* the bot trading this round, or -1: you */
static int8_t botPos[MAXB];
static void bot_prep(void) {
    int n = nbars < MAXB ? nbars : MAXB; int8_t p = 0;
    for (int i = 0; i < n; i++) {
        int c = BC(i);
        switch (botI) {
        case 0: p = sdir[i] > 0 ? 1 : -1; break;
        case 1: if (i && ps[0][i - 1] < 30 && ps[0][i] >= 30) p = 1; else if (i && ps[0][i - 1] > 70 && ps[0][i] <= 70) p = -1; break;
        case 2: p = ps[0][i] > ps[1][i] ? 1 : -1; break;
        case 3: if (c < is[2][i]) p = 1; else if (c > is[1][i]) p = -1; else if ((p > 0 && c >= is[0][i]) || (p < 0 && c <= is[0][i])) p = 0; break;
        case 4: p = sdir[i] < 0 ? 1 : -1; break;
        case 5: p = c > is[0][i] ? 1 : -1; break;
        case 6: for (uint8_t q = 0; q < nlv; q++) if (lv[q].brk == i) p = lv[q].res ? 1 : -1; break;
        default: p = 0;
        }
        botPos[i] = p;
    }
}

/* Racing a bot: you trade, the bot trades the same chart beside you, on each bar's close, at the same size. */
static bool botRace;                 /* racing the bot rather than watching it */
static uint8_t botBeat;              /* the bots you have beaten, a bit each (saved) */
static int8_t botDir; static float botEntry, botReal; static int botLast, botLead;
typedef struct { int bar; int8_t dir; } BotMark;
#define MAXBM 64
static BotMark bm[MAXBM]; static uint8_t nbm;
static float leadCallT = -9; static int8_t leadCall;   /* the last change of lead, called beside the rival for 1.6 s */
static void bot_race_reset(void) { botDir = 0; botEntry = 0; botReal = 0; botLast = lead - 1; nbm = 0; botLead = 0; }
static float bot_open(void) { return botDir ? NOTIONAL * (rawp(BC(botLast)) / botEntry - 1.0f) * botDir - FEE : 0; }
static float bot_total(void) { return botReal + bot_open(); }
static void bot_step(void) {
    while (botLast < kf - 1 && botLast + 1 < MAXB) {
        int b = ++botLast; int8_t want = botPos[b];
        if (botDir && bot_open() <= LIQ_USD) { botReal += LIQ_USD; botDir = 0; if (nbm < MAXBM) { bm[nbm].bar = b; bm[nbm].dir = 0; nbm++; } }
        if (want != botDir) {
            if (botDir) botReal += bot_open();
            botDir = want; if (want) botEntry = rawp(BC(b));
            if (nbm < MAXBM) { bm[nbm].bar = b; bm[nbm].dir = want; nbm++; }
            SFX(SFX_CLINK, 0);
        }
    }
}

/* a series as a polyline over the closed visible bars; width 1 or 2 */
static void ind_line(const int *s, int first, int last, uint8_t col, int w) {
    gfx_SetColor(col);
    int px = XI(first), py = Y(s[first]);
    for (int i = first + 1; i <= last; i++) {
        int x = XI(i), y = Y(s[i]);
        gfx_Line(px, py, x, y); if (w > 1) gfx_Line(px, py + 1, x, y + 1);
        px = x; py = y;
    }
}
static void band_fill(const int *a, const int *b, int i, uint8_t col) {
    int ya = Y(a[i]), yb = Y(b[i]), t = ya < yb ? ya : yb, h = ya < yb ? yb - ya : ya - yb;
    if (h > 0) { gfx_SetColor(col); gfx_FillRectangle(XI(i) - SLOT / 2, t, SLOT, h); }
}
static void label_chip(int x, int y, const char *t, uint8_t face, bool up) { /* label_up sits under its point, label_down over it */
    int w = textw(t, 1) + 6, ty = up ? y + 5 : y - 15;
    if (x - w / 2 < 2) x = w / 2 + 2;
    if (x + w / 2 > PR - 2) x = PR - 2 - w / 2;
    tri(x, up ? y + 1 : y - 5, 3, 4, up, face);
    gfx_SetColor(face); gfx_FillRectangle(x - w / 2, ty, w, 11);
    text_on(t, x - w / 2 + 3, ty + 2, C_INK, 1, face);
}

static void ind_back(int first, int last) {
    if (last < first || preset != 1) return; /* bands and zones are lines only on this LCD; a squeeze still tints its bars */
    for (int i = first; i <= last; i++) {
        if (preset == 0) band_fill(is[0], is[4], i, sdir[i] > 0 ? I_BLUEF : I_VIOF);
        else if (preset == 1) {
            if (sdir[i]) { gfx_SetColor(I_SQZ); gfx_FillRectangle(XI(i) - SLOT / 2, PT - 8, SLOT, pb - PT + 8); }
            (void)band_fill;
        } else if (preset == 2) {
            int body = (BO(i) + BC(i)) / 2;
            int ys = Y(is[0][i]), yb = Y(body), t = ys < yb ? ys : yb, h = ys < yb ? yb - ys : ys - yb;
            if (h > 0) { gfx_SetColor(sdir[i] < 0 ? I_STUP : I_STDN); gfx_FillRectangle(XI(i) - SLOT / 2, t, SLOT, h); }
        } else band_fill(is[1], is[2], i, I_GOLDF);
    }
}

static void ind_front(int first, int last) {
    if (last < first) return;
    if (preset == 0) {
        static const uint8_t UPC[5] = { I_BLUE, I_BLUE7, I_BLUE5, I_BLUE35, I_BLUE25 }, DNC[5] = { I_VIO, I_VIO7, I_VIO5, I_VIO35, I_VIO25 };
        for (int j = 4; j >= 0; j -= 2) {
            int px = XI(first), py = Y(is[j][first]);
            for (int i = first + 1; i <= last; i++) {
                int x = XI(i), y = Y(is[j][i]);
                gfx_SetColor(sdir[i] > 0 ? UPC[j] : DNC[j]);
                gfx_Line(px, py, x, y); if (j == 0 || j == 4) gfx_Line(px, py + 1, x, y + 1);
                px = x; py = y;
            }
        }
    } else if (preset == 1) {
        ind_line(is[1], first, last, I_BLUE8, 1); ind_line(is[2], first, last, I_BLUE8, 1); ind_line(is[0], first, last, I_GOLD, 1);
    } else if (preset == 2) {
        for (int i = first + 1; i <= last; i++) {
            if (sdir[i] != sdir[i - 1]) continue; /* style_linebr: the line breaks where the trend flips */
            gfx_SetColor(sdir[i] < 0 ? I_BLUE : I_VIO);
            int x0 = XI(i - 1), y0 = Y(is[0][i - 1]), x1 = XI(i), y1 = Y(is[0][i]);
            gfx_Line(x0, y0, x1, y1); gfx_Line(x0, y0 + 1, x1, y1 + 1);
        }
        for (int i = first + 1; i <= last; i++) {
            if (sdir[i] < 0 && sdir[i - 1] > 0) label_chip(XI(i), Y(is[0][i]), "BUY", C_TEXT, true);
            else if (sdir[i] > 0 && sdir[i - 1] < 0) label_chip(XI(i), Y(is[0][i]), "SELL", C_BEAR, false);
        }
    } else {
        for (uint8_t n = 0; n < nlv; n++) {
            Lvl *L = &lv[n];
            if (L->conf > last) continue;
            bool broke = L->brk >= 0 && L->brk <= last;
            int x0 = XI(L->start), x1 = broke ? XI(L->brk) : PR, y = Y(L->lvl);
            if (x1 < 0 || y < PT - 10 || y > pb) continue;
            if (x0 < 0) x0 = 0;
            gfx_SetColor(L->res ? (broke ? I_BEAR3 : C_EDGEDN) : (broke ? I_TEXT3 : I_TEXT8));
            gfx_HorizLine(x0, y, x1 - x0); gfx_HorizLine(x0, y + 1, x1 - x0);
            if (broke && x1 >= 0 && x1 < PR) label_chip(x1, y, "BREAK", L->res ? C_TEXT : C_BEAR, L->res);
        }
        ind_line(is[1], first, last, I_GOLD4, 1); ind_line(is[2], first, last, I_GOLD4, 1); ind_line(is[0], first, last, I_GOLD, 2);
    }
}

/* the pane under the chart: RSI or MACD */
static void ind_pane(int first, int last) {
    if (preset > 1) return;
    int top = pb + 8, bot = PB - 2, h = bot - top;
    gfx_SetColor(C_GRID); gfx_HorizLine(0, pb + 4, PR);
    if (last < first) return;
    char lab[20];
    if (preset == 0) {
        int y70 = top + h * 30 / 100, y50 = top + h / 2, y30 = top + h * 70 / 100;
        gfx_SetColor(I_GRAYF); gfx_FillRectangle(0, y70, PR, y30 - y70);
        hline_dash(0, PR, y70, I_GRAY6, 3, 3, 0); hline_dash(0, PR, y30, I_GRAY6, 3, 3, 0); hline_dash(0, PR, y50, I_GRAY3, 1, 3, 0);
        int px = XI(first), py = bot - h * ps[0][first] / 100;
        for (int i = first + 1; i <= last; i++) {
            int r = ps[0][i], x = XI(i), y = bot - h * r / 100;
            if (r > 70) { gfx_SetColor(I_TEXT3); gfx_FillRectangle(x - SLOT / 2, y, SLOT, y70 - y); }
            else if (r < 30) { gfx_SetColor(I_BEAR3); gfx_FillRectangle(x - SLOT / 2, y30, SLOT, y - y30); }
            gfx_SetColor(r > 70 ? C_TEXT : r < 30 ? C_BEAR : I_GOLD);
            gfx_Line(px, py, x, y); gfx_Line(px, py + 1, x, y + 1);
            px = x; py = y;
        }
        strcpy(lab, "RSI "); digits(lab + 4, ps[0][last], 0, 0);
        text(lab, 4, top - 2, I_GOLD, 1);
    } else {
        int mx = 1;
        for (int i = first; i <= last; i++) for (int j = 0; j < 3; j++) { int a = ps[j][i] < 0 ? -ps[j][i] : ps[j][i]; if (a > mx) mx = a; }
        int z = top + h / 2;
        #define PY(v) (z - (int)((long)(v) * (h / 2) / mx))
        gfx_SetColor(I_GRAY6); gfx_HorizLine(0, z, PR);
        for (int i = first; i <= last; i++) {
            int hv = ps[2][i], hp = i ? ps[2][i - 1] : hv, y = PY(hv);
            gfx_SetColor(hv >= 0 ? (hv > hp ? C_TEXT : I_TEXT45) : (hv < hp ? C_BEAR : I_BEAR45));
            if (y < z) gfx_FillRectangle(XI(i) - BODY / 2, y, BODY, z - y); else if (y > z) gfx_FillRectangle(XI(i) - BODY / 2, z, BODY, y - z);
        }
        int ax = XI(first), am = PY(ps[0][first]), as = PY(ps[1][first]);
        for (int i = first + 1; i <= last; i++) {
            int x = XI(i), m = PY(ps[0][i]), s = PY(ps[1][i]);
            gfx_SetColor(I_BLUE); gfx_Line(ax, as, x, s);
            gfx_SetColor(I_GOLD); gfx_Line(ax, am, x, m); gfx_Line(ax, am + 1, x, m + 1);
            ax = x; am = m; as = s;
        }
        #undef PY
        text("MACD", 4, top - 2, I_GOLD, 1);
    }
}

/* ---- effects ------------------------------------------------------------------------------------- */
static void floater(const char *t, int x, int y, uint8_t col, bool big, bool cash) {
    uint8_t s = 0; float least = 99;
    for (uint8_t i = 0; i < 3; i++) { if (!flo[i].on) { s = i; break; } if (flo[i].life < least) { least = flo[i].life; s = i; } }
    Floater *f = &flo[s];
    f->on = true; f->cash = cash; f->big = big; f->col = col; f->x = x; f->y = y; f->life = f->max = 1.7f;
    strncpy(f->txt, t, 23); f->txt[23] = 0;
}
static Mark *add_mark(uint8_t kind, uint8_t col, const char *t, float life) {
    Mark *m = &marks[0];
    for (uint8_t i = 0; i < NMK; i++) { if (!marks[i].on) { m = &marks[i]; break; } if (marks[i].t0 < m->t0) m = &marks[i]; }
    m->on = true; m->kind = kind; m->col = col; m->t0 = now_s; m->life = life;
    strncpy(m->txt, t, 19); m->txt[19] = 0;
    return m;
}
static int floatX(void) { return PR - 20; }
static int rise(int y, int above) { int lo = PT + above + 66; int r = y > lo ? y : lo; return r < pb - 10 ? r : pb - 10; }

/* ---- Candle Vision: the web engine's own setups for this window (data/cv/setups.cjs), drawn and locked like core.js ---- */
#define MAXS 40
#define SREC 35
#define READ_WINDOW 8
typedef struct { int at, start, entry, risk, res; int8_t dir; uint8_t conf; bool win; const char *name; } Setup;
static const uint8_t *SS; static uint8_t nset;
static uint8_t locked[MAXS];
static int lockI = -1; static float lockT = -9;           /* the setup locked on, and when */
static uint8_t resShown[MAXS];
static uint8_t combo, bestCombo, reads;

static void get_setup(uint8_t i, Setup *s) {
    const uint8_t *p = SS + (uint24_t)i * SREC;
    s->at = p[0] | (p[1] << 8); s->start = p[2] | (p[3] << 8); s->dir = (int8_t)p[4]; s->conf = p[5];
    s->entry = p[6] | (p[7] << 8); s->risk = p[8] | (p[9] << 8); s->win = p[10];
    int r = p[11] | (p[12] << 8); s->res = r == 0xFFFF ? -1 : r;
    s->name = (const char *)(p + 13);
}
/* "Bullish Engulfing" -> "ENGULFING": the bracket's short name */
static void short_name(const char *n, char *o, int max) {
    if (!strncmp(n, "Bullish ", 8)) n += 8; else if (!strncmp(n, "Bearish ", 8)) n += 8;
    int i = 0;
    for (; *n && i < max - 1; n++) { char c = *n; if (c >= 'a' && c <= 'z') c -= 32; if (c == '-') c = ' '; o[i++] = c; }
    o[i] = 0;
}
static int pat_hi(const Setup *s) { int h = 0; for (int i = s->start; i <= s->at; i++) if (BH(i) > h) h = BH(i); return h; }
static int pat_lo(const Setup *s) { int l = 65535; for (int i = s->start; i <= s->at; i++) if (BL(i) < l) l = BL(i); return l; }

/* the pattern inks (VISION_INK dark): bullish #42c86c, bearish #ff626c */
#define C_VUP C_GAIN
enum { C_VDN = 100, C_VUP45, C_VDN45, C_VUP55, C_VDN55, C_VUPZ, C_VDNZ, C_VUPZ2, C_VDNZ2, C_VUP3, C_VUP6 };
static void vision_palette(void) {
    setp(C_VDN, 0xff626cUL); setai(C_VUP45, RGB_GAIN, 115); setai(C_VDN45, 0xff626cUL, 115);
    setai(C_VUP55, RGB_GAIN, 141); setai(C_VDN55, 0xff626cUL, 141);
    setai(C_VUPZ, RGB_TEXT, 15); setai(C_VDNZ, RGB_BEAR, 18); setai(C_VUPZ2, RGB_TEXT, 31); setai(C_VDNZ2, RGB_BEAR, 31);
    setai(C_VUP3, RGB_TEXT, 77); setai(C_VUP6, RGB_TEXT, 154);
}

/* Every setup that has printed stays marked: the locked one and the two newest get a bracket and a name, older ones a tick.
 * Once the market decides it, a dashed line to the target or the stop and a check or a cross. */
static void draw_setup_marks(bool hidden) {
    if (hidden) return;
    int last = -1;
    for (uint8_t i = 0; i < nset; i++) { Setup s; get_setup(i, &s); if (s.at < kf) last = i; }
    for (uint8_t i = 0; i < nset; i++) {
        Setup s; get_setup(i, &s);
        if (s.at >= kf) break;
        int xa = XI(s.start) - SLOT * 2 / 5, xb = XI(s.at) + SLOT * 2 / 5;
        if (xb < 0) continue;
        bool up = s.dir > 0, isLock = (int)i == lockI;
        int y = up ? Y(pat_lo(&s)) + 9 : Y(pat_hi(&s)) - 9;
        if (isLock && now_s - lockT < 2.9f) continue; /* the reticle is drawing this one */
        if (fog() && s.at < kf - 12) continue;
        if (!isLock && (int)i < last - 1) {
            gfx_SetColor(up ? C_VUP45 : C_VDN45); gfx_FillRectangle((xa + xb) / 2 - 1, y - (up ? 3 : 0), 3, 3);
        } else {
            gfx_SetColor(isLock ? (up ? C_VUP : C_VDN) : (up ? C_VUP55 : C_VDN55));
            gfx_HorizLine(xa, y, xb - xa + 1);
            gfx_VertLine(xa, up ? y - 4 : y, 5); gfx_VertLine(xb, up ? y - 4 : y, 5);
            char sh[24]; short_name(s.name, sh, 24);
            int w = textw(sh, 1), tx = (xa + xb) / 2 - w / 2;
            if (tx < 2) tx = 2;
            if (tx + w > PR - 2) tx = PR - 2 - w;
            text(sh, tx, up ? y + 4 : y - 12, up ? C_VUP55 : C_VDN55, 1);
        }
        if (s.res >= 0 && kf > s.res) { /* resolved: only once the deciding bar has closed */
            int pr = s.win ? s.entry + s.dir * 2 * s.risk : s.entry - s.dir * s.risk;
            int xr = XI(s.res), yr = Y(pr);
            hline_dash(XI(s.at), xr, yr, s.win ? C_VUP3 : I_BEAR45, 2, 3, 0);
            gfx_SetColor(s.win ? C_TEXT : C_BEAR);
            int gy = yr + ((s.win == up) ? -8 : 8);
            if (s.win) { gfx_Line(xr - 3, gy, xr - 1, gy + 2); gfx_Line(xr - 1, gy + 2, xr + 3, gy - 2); }
            else { gfx_Line(xr - 3, gy - 3, xr + 3, gy + 3); gfx_Line(xr - 3, gy + 3, xr + 3, gy - 3); }
            if (!resShown[i]) {
                resShown[i] = 1;
                if (!(pos.on && pos.setup == (int)i)) {
                    char t[28]; short_name(s.name, t, 14); strcat(t, s.win ? " HIT TARGET" : " STOPPED");
                    Mark *m = add_mark(3, s.win ? C_TEXT : C_BEAR, t, 1.5f); m->q0 = ((long)s.res << 10) + 512; m->v0 = pr;
                }
            }
        }
    }
}

/* The lock: brackets close in on the pattern with an overshoot, a scan line sweeps it, and the plan shows while you are flat */
static void draw_reticle(void) {
    if (lockI < 0) return;
    float age = now_s - lockT;
    if (age > 2.6f && !callOn) return;
    Setup s; get_setup((uint8_t)lockI, &s);
    bool up = s.dir > 0;
    uint8_t col = callOn ? C_TEXT : (up ? C_VUP : C_VDN);
    int x0 = XI(s.start) - SLOT * 4 / 5, x1 = XI(s.at) + SLOT * 4 / 5, y0 = Y(pat_hi(&s)) - 10, y1 = Y(pat_lo(&s)) + 10;
    float t = age / 0.35f; if (t > 1) t = 1;
    float u = 1 - t, e = 1 - u * u * u * cos_f(t * 4);
    int sp = (int)((1 - e) * 44), L = 12;
    if (age > 2.1f && !callOn) { if (((int)(age * 20)) & 1) return; } /* fades out over the last half second */
    float sw = age / 0.5f;
    if (sw < 1) { int xs = x0 + (int)((float)(x1 - x0) * (1 - (1 - sw) * (1 - sw))); gfx_SetColor(col); gfx_FillRectangle(xs - 1, y0, 2, y1 - y0); }
    gfx_SetColor(col);
    int cx[4] = { x0 - sp, x1 + sp, x0 - sp, x1 + sp }, cy[4] = { y0 - sp, y0 - sp, y1 + sp, y1 + sp }, dx[4] = { 1, -1, 1, -1 }, dy[4] = { 1, 1, -1, -1 };
    for (int c = 0; c < 4; c++) {
        for (int w = 0; w < 2; w++) {
            gfx_HorizLine(dx[c] > 0 ? cx[c] : cx[c] - L, cy[c] + w * dy[c], L);
            gfx_VertLine(cx[c] + w * dx[c], dy[c] > 0 ? cy[c] : cy[c] - L, L);
        }
    }
    if (callOn) { /* Call It: a countdown ring where the answer candle prints, and two marks: up or down */
        int R = 26, qx = x1 + SLOT + R + 6, qy = (y0 + y1) / 2;
        if (qx > PR - R - 4) qx = PR - R - 4;
        float left = callLeft / CALL_SECONDS; if (left < 0) left = 0;
        gfx_SetColor(left < 0.3f ? C_BEAR : C_TEXT);
        int n = (int)(left * 40);
        for (int i = 0; i < n; i++) { float a = (float)i * 0.15708f; gfx_FillRectangle(qx + (int)(sin_f(a) * R) - 2, qy - (int)(cos_f(a) * R) - 2, 4, 4); }
        tri(qx, qy - 13, 7, 7, true, C_TEXT); tri(qx, qy + 6, 7, 7, false, C_TEXT);
        return;
    }
    if (!pos.on && age > 0.7f && !blind()) { /* the plan it implies: the stop and 2R, drawn out to the right */
        int ys = Y(s.entry - s.dir * s.risk), yt = Y(s.entry + s.dir * 2 * s.risk), xa = x1 + 4;
        hline_dash(xa, PR, yt, C_VUP6, 3, 3, 0); hline_dash(xa, PR, ys, I_BEAR45, 3, 3, 0);
        text_r("2R", PR - 4, yt - 10, C_MUTED, 1); text_r("STOP", PR - 4, ys + 3, C_MUTED, 1);
    }
}

/* The caption RunOverlay hangs under the HUD: PATTERN LOCKED, the name, the side and the confidence */
static void draw_caption(void) {
    if (lockI < 0) return;
    float age = now_s - lockT;
    if (age > 2.6f && !callOn) return;
    Setup s; get_setup((uint8_t)lockI, &s);
    bool up = s.dir > 0;
    int x = 122, y = 34;   /* under the clock pill, right of the score plate */
    const char *kick = callOn ? "CALL IT" : callTag ? callTag : "PATTERN LOCKED";
    gfx_SetColor(C_ORANGE); gfx_FillRectangle(x, y + 1, 5, 5);
    text(kick, x + 9, y, C_ORANGE, 1);
    if (callOn) { text("WHICH WAY?", x, y + 12, C_TEXT, 2); return; }
    if (blind()) { text("SETUP SPOTTED", x, y + 12, C_TEXT, 2); text("BLIND", x, y + 32, C_MUTED, 1); return; }
    char nm[24]; strncpy(nm, s.name, 23); nm[23] = 0;
    for (char *c = nm; *c; c++) if (*c >= 'a' && *c <= 'z') *c -= 32;
    uint8_t sc = textw(nm, 2) <= PR - 4 - x ? 2 : 1;   /* clear of the price axis */
    text(nm, x, y + 12, up ? C_VUP : C_VDN, sc);
    char w[20]; strcpy(w, up ? "BULLISH " : "BEARISH "); char *o = digits(w + 8, s.conf, 0, 0); *o++ = '%'; *o = 0;
    text(w, x, y + 12 + 8 * sc + 4, C_MUTED, 1);
    mark(x + textw(w, 1) + 4, y + 12 + 8 * sc + 5, up, up ? C_VUP : C_VDN);
}

static void vis_load(const uint8_t *p) { nset = p[0]; if (nset > MAXS) nset = MAXS; SS = p + 1; }
/* the ride's plan when it rides a setup the way it points: the setup's stop, 1R and 2R from your own entry (planOf) */
static bool plan_of(int *stop, int *one, int *target) {
    if (!pos.on || pos.setup < 0) return false;
    Setup s; get_setup((uint8_t)pos.setup, &s);
    if (pos.dir != s.dir) return false;
    int st = s.entry - s.dir * s.risk, risk = pos.dir * (pos.entry - st);
    if (risk <= 0) return false;
    *stop = st; *one = pos.entry + pos.dir * risk; *target = pos.entry + pos.dir * 2 * risk;
    return true;
}


static void openPos(int8_t dir) {
    if (pos.on) return;
    if (mode == M_SNIPER) { if (!bullets) return; bullets--; if (!bullets) floater("LAST BULLET", floatX(), PT + 60, C_ORANGE, false, false); }
    pos.on = true; pos.dir = dir; pos.entryQ = kq; pos.entry = fc; pos.entryRaw = rawp(fc); pos.t0 = now_s;
    SFX(SFX_OPEN, dir);
    /* the size: $25,000 (Sniper triples it); Blow-Up rides its bank at the leverage reached, liquidating at -80% of it */
    pos.bankAtOpen = bank;
    pos.notional = mode == M_BLOWUP ? (float)(long)(bank * lev) : mode == M_SNIPER ? 3 * NOTIONAL : NOTIONAL;
    pos.fee = 2.0f * 3.0f / 10000.0f * pos.notional;
    pos.liq = mode == M_BLOWUP ? -0.8f * bank : LIQ_USD;
    pos.liqv = vof(pos.entryRaw * (1.0f + (pos.liq + pos.fee) / pos.notional * dir));
    pos.worst = 0; pos.beT = -9; pos.upset = false; pos.rung = 0; pos.broke = false;
    /* the setup it rides: the newest printed one within the read window (core.js openPos) */
    pos.setup = -1;
    for (uint8_t i = 0; i < nset; i++) { Setup st; get_setup(i, &st); if (st.at < kf && kf - st.at <= READ_WINDOW) pos.setup = i; }
    rides++; rode = true; lastAct = elapsed;
    Mark *b = add_mark(2, dir > 0 ? C_GAIN : C_BEAR, "", 0.45f); b->q0 = kq; b->v0 = fc; /* the fill bursts out of the price */
    shake = shake > 1.5f ? shake : 1.5f;
}

/* every ride of the round, for the recap (the app's S.log) */
typedef struct { long q0, q1; int v0, v1; int8_t dir; float pnl; } RideLog;
#define MAXLOG 40
static RideLog rlog[MAXLOG]; static uint8_t nlog;
static void closePos(uint8_t reason) { /* 0 release, 1 flip, 2 liq, 3 end */
    if (!pos.on) return;
    int price = fc;
    float pnl = reason == 2 ? pos.liq : ridePnl(price);
    pos.on = false;
    if (mode == M_BLOWUP) { bank += pnl; if (bank > peakBank) peakBank = bank; }
    /* a ride on a setup, the way it pointed: the combo builds while they pay */
    bool read = false;
    if (pos.setup >= 0) { Setup st; get_setup((uint8_t)pos.setup, &st); read = st.dir == pos.dir; }
    if (reason == 2) { press.on = false; lockout = true; }
    bool good = pnl > 0;
    realized += pnl; if (good) wins++; if (reason == 2) liqs++;
    /* the trade stays on the chart: a box from entry to exit */
    if (nex == MAXEX) { memmove(exits, exits + 1, sizeof(Exit) * (MAXEX - 1)); nex--; }
    Exit *e = &exits[nex++];
    e->dir = pos.dir; e->good = good; e->q0 = pos.entryQ; e->v0 = pos.entry; e->q1 = kq; e->v1 = price; e->t0 = now_s;
    money_to(e->money, pnl, false);
    if (nlog < MAXLOG) { RideLog *L = &rlog[nlog++]; L->q0 = pos.entryQ; L->v0 = pos.entry; L->q1 = kq; L->v1 = price; L->dir = pos.dir; L->pnl = pnl; }
    /* the ride's path glows, then dissolves */
    Trail *t = !trails[0].on ? &trails[0] : !trails[1].on ? &trails[1] : trails[0].age > trails[1].age ? &trails[0] : &trails[1];
    t->on = true; t->good = good; t->age = 0; t->n = 0;
    long st = (kq - pos.entryQ) / 22; if (st < 128) st = 128;
    for (long q = pos.entryQ; q < kq && t->n < 23; q += st) { t->q[t->n] = q; t->v[t->n] = price_q(q); t->n++; }
    t->q[t->n] = kq; t->v[t->n] = price; t->n++;
    /* impact scales with the result */
    int y = Y(price);
    char m[24]; money_to(m, pnl, false);
    if (read && good) { combo++; reads++; if (combo > bestCombo) bestCombo = combo; wonKinds |= 1UL << (pos.setup & 31); } else if (!good) combo = 0;
    if (pos.setup >= 0) ridden |= 1UL << (pos.setup & 31);
    if (good && pos.dir < 0) shortWins++;
    if (good && pos.worst <= COMEBACK_USD) comebacks++;
    if (reason == 2) {
        shake = 9; hit = 0.16f; flashA = 1; flashCol = RGB_BEAR; SFX(SFX_LIQ, 0);
        add_mark(0, C_BEAR, "LIQUIDATED", 1.6f)->v = price;
        char l[28]; strcpy(l, "LIQUIDATED "); strcat(l, m);
        floater(l, floatX(), rise(y, 0), C_BEAR, true, true);
    } else if (good) {
        bool big = pnl > 1200;
        SFX(big ? SFX_BIG : SFX_WIN, combo);
        if (read && combo >= 3) SFX(SFX_COMBO, combo);
        shake = 2 + pnl / 400; if (shake > 8) shake = 8;
        hit = big ? 0.12f : 0.05f + (pnl / 20000 < 0.05f ? pnl / 20000 : 0.05f);
        if (big && slowmo < 0.45f) slowmo = 0.45f;
        if (big) { flashA = 0.7f; flashCol = RGB_TEXT; }
        bool comeback = pos.worst <= COMEBACK_USD;
        int fy = rise(y, comeback ? 38 : 0);
        floater(m, floatX(), fy, C_BULL, pnl > 250, true);
        if (read) floater("READ", floatX(), fy + 22, C_ORANGE, false, false);
        kickT = now_s;
        if (comeback) { if (slowmo < 0.35f) slowmo = 0.35f; floater("COMEBACK", floatX(), fy - 38, C_ORANGE, true, false); }
        if (read && combo >= 2) { char st[16]; st[0] = 'x'; char *o = digits(st + 1, combo, 0, 0); strcpy(o, " COMBO"); floater(st, floatX(), fy - (comeback ? 76 : 38), C_ORANGE, combo >= 3, false); }
        Mark *b = add_mark(2, C_TEXT, "", 0.5f); b->q0 = kq; b->v0 = price;
    } else {
        shake = 4; hit = 0.04f; flashA = 0.35f; flashCol = RGB_BEAR; SFX(SFX_LOSS, 0);
        floater(m, floatX(), rise(y, 0), C_BEAR, false, true);
    }
    /* near miss: after 8 candles, say if the move kept going */
    if (reason != 2 && reason != 3) {
        for (uint8_t i = 0; i < 4; i++) if (!checks[i].on) {
            Check *c = &checks[i];
            c->on = true; c->at = kf + 8; c->exitI = kf; c->price = price; c->pnl = pnl; c->entry = pos.entry; c->dir = pos.dir;
            break;
        }
    }
    lastAct = elapsed;
}

static void due_checks(void) {
    for (uint8_t i = 0; i < 4; i++) {
        Check *c = &checks[i];
        if (!c->on || kf < c->at) continue;
        c->on = false;
        int far = c->price, farK = c->exitI;
        for (int j = c->exitI + 1; j <= c->exitI + 8 && j < nbars; j++) {
            int x = c->dir > 0 ? BH(j) : BL(j);
            if ((c->dir > 0 && x > far) || (c->dir < 0 && x < far)) { far = x; farK = j; }
        }
        float extra = c->dir * (rawp(far) - rawp(c->price)) / rawp(c->entry) * NOTIONAL;
        long pc = (long)c->pnl; if (pc < 0) pc = -pc; float need = (float)pc * 0.6f; if (need < 300) need = 300;
        if (extra > need) {
            char t[20]; char *o = money_to(t, extra, false); strcpy(o, " LEFT");
            Mark *mk = add_mark(1, C_TEXT, t, 2.6f);
            mk->q0 = ((long)c->exitI << 10) + 512; mk->v0 = c->price; mk->q1 = ((long)farK << 10) + 512; mk->v1 = far;
        }
    }
}


/* ---- drawing: chart ------------------------------------------------------------------------------ */
static int firstHourBar(int first) { /* the first visible bar that opens an hour */
    uint32_t t = W.start + (uint32_t)first * 300;
    int r = (int)(t % 3600);
    return first + (r ? (3600 - r) / 300 : 0);
}

/* As the app's drawGrid: solid price lines carried up behind the HUD, and dotted time lines (1 on, 5 off) from the top
 * to the plot's floor on round clock times at least 72 px apart: at 9 px a 5 minute bar, every hour. */
static void draw_grid(void) {
    gfx_SetColor(C_GRID);
    for (long g = (gridLoRaw / gridStep + 1) * gridStep; g < gridHiRaw + (gridHiRaw - gridLoRaw) / 2; g += gridStep) {
        int y = Y(vof((float)g));
        if (y >= 0 && y < pb) gfx_HorizLine(0, y, PR);
    }
    int first = kf - VIS; if (first < 1) first = 1;
    for (int i = firstHourBar(first); i < kf + VIS; i += 12) {
        int x = XI(i);
        if (x < 0) continue;
        if (x >= PR) break;
        for (int y = 0; y < pb; y += 6) gfx_SetPixel(x, y);
    }
}

static void candle_px(int x, int o, int h, int l, int c, bool dim) {
    if (x < -BODY || x > PR + BODY) return;
    bool isup = c >= o;
    int yh = Y(h), yl = Y(l), yo = Y(o), yc = Y(c);
    int t = isup ? yc : yo, b = isup ? yo : yc;
    bool in = x >= BODY && x < PR - BODY && yh >= 0 && yl < 240; /* wholly on screen: skip graphx's clipping */
#ifdef SR_TDECK
    if (chartStyle >= 2 && !dim && !fog()) { /* Emoji (the app's emoji-candles.js): a tinted body, the wick, and whole emoji
                                             * stacked from the open toward the close, at least one */
        gfx_SetColor(isup ? C_DUPB : C_DDNB);
        gfx_VertLine(x, yh, yl - yh + 1);
        gfx_FillRectangle(x - BODY / 2, t, BODY, b - t + 1);
        int h = b - t, sz = 10, pitch = 7;
        if (h < sz) sr_emoji(chartStyle - 2, isup, x - sz / 2, t + h / 2 - sz / 2);
        else for (int n = (h - sz) / pitch + 1, i = 0; i < n; i++) sr_emoji(chartStyle - 2, isup, x - sz / 2, isup ? yo - sz - i * pitch : yo + i * pitch);
        return;
    }
#endif
    gfx_SetColor(dim ? (isup ? C_DUPB : C_DDNB) : (isup ? C_UPW : C_DNW));
    if (in) gfx_VertLine_NoClip(x, yh, yl - yh + 1); else gfx_VertLine(x, yh, yl - yh + 1);
    if (isup && hollowUp) {
        gfx_SetColor(C_BG); if (in) gfx_FillRectangle_NoClip(x - BODY / 2, t, BODY, b - t + 1); else gfx_FillRectangle(x - BODY / 2, t, BODY, b - t + 1);
        gfx_SetColor(dim ? C_DUPB : C_UPO); gfx_Rectangle(x - BODY / 2, t, BODY, b - t + 1);
        return;
    }
    gfx_SetColor(dim ? (isup ? C_DUPB : C_DDNB) : (isup ? C_UPB : C_DNB));
    if (in) gfx_FillRectangle_NoClip(x - BODY / 2, t, BODY, b - t + 1); else gfx_FillRectangle(x - BODY / 2, t, BODY, b - t + 1);
}

static void draw_line_style(int first, bool dim) {
    /* Line (the app's drawLine): through the closes, a faint fill to the floor, the newest step in the live colour */
    int px = XI(first), py = Y(BC(first));
    for (int i = first + 1; i <= kf; i++) {
        int x = XI(i), y = Y(i == kf ? fc : BC(i));
        if (!dim) { gfx_SetColor(I_LINEF); for (int c = px; c < x; c++) { int yy = py + (y - py) * (c - px) / (x - px); if (c >= 0 && c < PR && yy < pb) gfx_VertLine(c, yy, pb - yy); } }
        uint8_t col = dim ? C_DUPB : i == kf ? (fc >= fo ? C_BULL : C_BEAR) : C_TEXT;
        gfx_SetColor(col); gfx_Line(px, py, x, y); gfx_Line(px, py + 1, x, y + 1);
        px = x; py = y;
    }
}
static void draw_candles(bool dim) {
    int first = kf - VIS; if (first < 0) first = 0;
    int fogK = fog() && scene == 1 ? kf - 12 : -99;
    if (chartStyle == 1 && !fog()) { draw_line_style(first, dim); return; }
    for (int i = first; i < kf; i++) {
        if (i < fogK - 4) continue;                      /* Fog of War: the last 12 candles, the tail fading out */
        candle_px(XI(i), BO(i), BH(i), BL(i), BC(i), dim || i < fogK);
    }
    if (dim) return;
    /* the candle that just closed: one short pulse of its outline */
    float e = (now_s - closeT) / 0.22f;
    if (e < 1 && closeI >= first) {
        int i = closeI, x = XI(i) - BODY / 2, yh = Y(BH(i)), yl = Y(BL(i));
        seta(D_PULSE, BC(i) >= BO(i) ? RGB_BULL : RGB_BEAR, 0.7f * (1 - e));
        gfx_SetColor(D_PULSE); gfx_Rectangle(x - 2, yh - 2, BODY + 4, yl - yh + 5);
    }
    int x = XI(kf);
    candle_px(x, fo, fh, fl, fc, false);
    /* the print edge, exactly where the price is */
    gfx_SetColor(fc >= fo ? C_BULL : C_BEAR); gfx_HorizLine(x - BODY / 2 - 1, Y(fc), BODY + 2);
}

static void draw_exits(bool back) { /* back: the box's wash, under the candles; front: its edge, fills and chip */
    for (uint8_t n = 0; n < nex; n++) {
        Exit *e = &exits[n];
        int x0 = X(e->q0), x1 = X(e->q1), y0 = Y(e->v0), y1 = Y(e->v1);
        if (x1 < -40) continue;
        float age = now_s - e->t0;
        if (n + 2 < nex) { /* an old trade: entry fill and exit bar only */
            if (back) continue;
            if (e->dir > 0) tri(x0, y0 + 3, 4, 8, true, C_OLDTRI); else tri(x0, y0 - 10, 4, 8, false, C_OLDTRI);
            gfx_SetColor(e->good ? C_OLDUP : C_OLDDN); gfx_FillRectangle(x1 - 1, y1 - 5, 2, 10);
            continue;
        }
        bool newest = n + 1 == nex;
        uint8_t df = newest ? D_EXF0 : D_EXF1, ds = newest ? D_EXS0 : D_EXS1;
        uint32_t col = e->good ? RGB_BULL : RGB_BEAR;
        float grow = age / 0.28f; if (grow > 1) grow = 1;
        float fresh = 1 - (age - 2.2f > 0 ? age - 2.2f : 0) / 0.8f; if (fresh < 0) fresh = 0;
        float g1 = 1 - grow, ease = 1 - g1 * g1 * g1;
        int xg = x0 + (int)((float)(x1 - x0) * ease);
        int top = y0 < y1 ? y0 : y1, hgt = y0 < y1 ? y1 - y0 : y0 - y1;
        seta(df, col, 0.02f + 0.08f * fresh); seta(ds, col, 0.35f + 0.5f * fresh);
        if (back) continue; /* the box's outline only: no wash on this LCD */
        (void)df;
        if (xg > x0) { gfx_SetColor(ds); gfx_Rectangle(x0, top, xg - x0, hgt + 1); }
        if (e->dir > 0) tri(x0, y0 + 3, 5, 9, true, C_TEXT); else tri(x0, y0 - 11, 5, 9, false, C_TEXT);
        if (grow >= 1) {
            gfx_SetColor(e->good ? C_BULL : C_BEAR); gfx_FillRectangle(x1 - 1, y1 - 7, 3, 14);
            float settle = (age - 1.5f) / 0.3f; if (settle > 1) settle = 1;
            float a = settle < fresh ? settle : fresh;
            if (newest && a > 0.35f) { /* the newest trade's result, then gone */
                int w = textw(e->money, 1) + 10, cx = x1 + 6;
                if (cx + w > PR - 2) cx = x1 - w - 12;
                seta(D_CHIP, col, a);
                gfx_SetColor(D_CHIP); gfx_FillRectangle(cx, y1 - 6, w, 13);
                text_on(e->money, cx + 5, y1 - 3, C_INK, 1, D_CHIP);
            }
        }
    }
}

static void draw_trails(void) {
    for (uint8_t n = 0; n < 2; n++) {
        Trail *t = &trails[n];
        if (!t->on) continue;
        float f = t->age / 1.1f;
        uint8_t d = n ? D_TR1 : D_TR0;
        seta(d, t->good ? RGB_BULL : RGB_BEAR, (1 - f) * 0.55f);
        int w = 1 + (int)(4 * f);
        gfx_SetColor(d);
        int px = X(t->q[0]), py = Y(t->v[0]);
        for (uint8_t i = 1; i < t->n; i++) {
            int x = X(t->q[i]), y = Y(t->v[i]);
            gfx_Line(px, py - w, x, y - w); gfx_Line(px, py, x, y); gfx_Line(px, py + w, x, y + w);
            px = x; py = y;
        }
    }
}

static int labTop = 999; /* the highest exit label this frame (target, stop, liq): the ticker gives way to one near the top */
static void exit_label(const char *t, int y, uint8_t col) {
    int top = lockI >= 0 && (now_s - lockT <= 2.6f || callOn) ? 76 : 30;   /* under the caption while it shows */
    if (y < top) y = top; if (y > 214) y = 214;   /* clear of the clock pill and the time row */
    text_r(t, PR - 8, y, col, 1); if (y < labTop) labTop = y;
}
static void draw_risk(void) {
#ifdef NO_RISK
    return;
#endif
    if (!pos.on) return;
    int x0 = X(pos.entryQ); if (x0 < 0) x0 = 0;
    int yl = Y(pos.liqv), ye = Y(pos.entry);
    int stop, one, target; bool plan = plan_of(&stop, &one, &target);
    if (plan) { /* the read's plan: a light zone to 2R, a red one to the stop, the 1R rung dashed */
        int yt = Y(target), ys = Y(stop), y1 = Y(one);
        int a = yt < ye ? yt : ye, b = yt < ye ? ye : yt;
        if (a < 0) a = 0;
        (void)a; (void)b;
        a = ys < ye ? ys : ye; b = ys < ye ? ye : ys;
        if (a < 0) a = 0;
        (void)a; (void)b;
        hline_dash(x0, PR, y1, pos.rung >= 1 ? C_VUP6 : C_VUP3, 3, 4, 0);
        gfx_SetColor(pos.rung >= 2 ? C_TEXT : C_VUP6); gfx_HorizLine(x0, yt, PR - x0); if (pos.rung >= 2) gfx_HorizLine(x0, yt + 1, PR - x0);
        gfx_SetColor(pos.broke ? C_BEAR : C_EDGEDN); gfx_HorizLine(x0, ys, PR - x0); if (pos.broke) gfx_HorizLine(x0, ys + 1, PR - x0);
        char t[24];
        strcpy(t, "TARGET "); money_to(t + 7, ridePnl(target), false); exit_label(t, pos.dir > 0 ? yt - 11 : yt + 4, C_TEXT);
        bool pastLiq = pos.dir * (stop - pos.liqv) < 0;
        if (pastLiq) strcpy(t, "STOP - PAST LIQ"); else { strcpy(t, "STOP "); money_to(t + 5, ridePnl(stop), false); }
        exit_label(t, pos.dir > 0 ? ys + 4 : ys - 11, C_BEAR);
    }
    /* the game's forced exit, always shown: it pulses as price closes in on it */
    if (yl > -10 && yl < PB) {
        float a = 0.35f + 0.6f * danger * (0.6f + 0.4f * sin_f(now_s * 1000.0f / (150.0f - 70.0f * danger)));
        seta(D_LIQ, RGB_BEAR, a);
        int w = 1 + (int)(danger * 1.5f + 0.5f);
        for (int d = 0; d < w; d++) hline_dash(x0, PR, yl + d, D_LIQ, 6, 4, 0);
        if (danger > 0.15f || !plan) { char t[20]; strcpy(t, "LIQ "); money_to(t + 4, pos.liq, false); exit_label(t, pos.dir > 0 ? yl + 4 : yl - 11, C_BEAR); }
    }
    float be = now_s - pos.beT;
    if (be < 0.5f) { /* breakeven crossed: the entry line flashes */
        seta(D_BE, RGB_TEXT, 0.9f * (1 - be / 0.5f));
        gfx_SetColor(D_BE); gfx_HorizLine(x0, ye, PR - x0); gfx_HorizLine(x0, ye + 1, PR - x0);
    }
}

static void draw_ride(void) {
#ifdef NO_RIDE
    return;
#endif
    if (!pos.on) return;
    bool g = openPnl >= 0;
    int xe = X(pos.entryQ), ye = Y(pos.entry), xl = X(kq), yl = Y(fc);
    if (xl < xe) xl = xe;
    /* the P&L wash between the entry line and the price path, strongest at the price */
    int top = yl < ye ? yl : ye, bot = yl < ye ? ye : yl, b1 = top + (bot - top) / 3, b2 = top + 2 * (bot - top) / 3;
    uint8_t w2 = g ? C_WU2 : C_WD2, nearC = yl < ye ? (g ? C_WU1 : C_WD1) : (g ? C_WU3 : C_WD3), farC = yl < ye ? (g ? C_WU3 : C_WD3) : (g ? C_WU1 : C_WD1);
    /* (the P&L wash between the entry and the price is not drawn here: on the calculator's LCD a large dark tint reads
     * as muddy bands, so the entry line, the price and the tag carry it) */
#if 0
    int i0 = (int)(pos.entryQ >> 10), first = kf - VIS; if (i0 < first) i0 = first;
    for (int i = i0; i <= kf; i++) {
        int xa = i == (int)(pos.entryQ >> 10) ? xe : XI(i) - SLOT / 2, xb = i == kf ? xl : XI(i) + SLOT / 2 + 1;
        if (xa < 0) xa = 0;
        if (xb > PR) xb = PR;
        if (xb <= xa) continue;
        int yp = Y(i == kf ? fc : BC(i)), a = yp < ye ? yp : ye, b = yp < ye ? ye : yp;
        if (b <= a) continue;
        int s1 = a < b1 ? (b < b1 ? b : b1) : a;
        if (s1 > a) { gfx_SetColor(nearC); gfx_FillRectangle(xa, a, xb - xa, s1 - a); }
        int s2 = s1 < b2 ? (b < b2 ? b : b2) : s1;
        if (s2 > s1) { gfx_SetColor(w2); gfx_FillRectangle(xa, s1, xb - xa, s2 - s1); }
        if (b > s2) { gfx_SetColor(farC); gfx_FillRectangle(xa, s2, xb - xa, b - s2); }
    }
#endif
    /* the entry line marches toward the price */
    hline_dash(xe, PR, ye, C_ENTRY, 4, 4, -(int)(now_s * 22.2f));
    if (xe >= -5) {
        gfx_SetColor(g ? C_BULL : C_BEAR); gfx_FillCircle(xe, ye, 4);
        gfx_SetColor(C_BG); gfx_FillCircle(xe, ye, 1);
    }
}

/* Axis labels: drawn once into a small sprite each, then blitted. graphx draws text at about 0.1 ms a character and a
 * label's digits cost another 0.5 ms; the labels only change when the scale crosses a step. */
#define NLC 10
typedef struct { long key; uint8_t show; gfx_sprite_t *spr; unsigned int used; } LabelC;
static LabelC lcache[NLC]; static unsigned int lclock;
static void axis_label(long g, uint8_t show, int x, int y) {
    LabelC *e = NULL, *old = &lcache[0];
    lclock++;
    for (uint8_t i = 0; i < NLC; i++) {
        if (lcache[i].spr && lcache[i].key == g && lcache[i].show == show) { e = &lcache[i]; break; }
        if (lcache[i].used < old->used) old = &lcache[i];
    }
    if (!e) {
        const char *s = price_raw(g, show);
        int w = textw(s, 1); if (w > 54) w = 54;
        if (old->spr) { free(old->spr); old->spr = NULL; }
        gfx_sprite_t *sp = gfx_MallocSprite(w, 8);
        if (!sp) { text(s, x, y, C_MUTED, 1); return; }
        /* draw it at the axis column's foot over the transparent index, grab it, put the floor back */
        gfx_SetColor(C_CLEAR); gfx_FillRectangle(PR, 231, w, 8);
        text(s, PR, 231, C_MUTED, 1);
        gfx_GetSprite(sp, PR, 231);
        gfx_SetColor(C_BG); gfx_FillRectangle(PR, 231, w, 8);
        old->spr = sp; old->key = g; old->show = show; e = old;
    }
    e->used = lclock;
    if (y >= 0 && y + 8 <= 240 && x >= 0 && x + e->spr->width <= 320) gfx_TransparentSprite_NoClip(e->spr, x, y);
}

static void draw_axes(bool live) {
    int y = Y(fc);
    gfx_SetColor(C_BG); gfx_FillRectangle(PR, 0, 320 - PR, 240);
    for (long g = (gridLoRaw / gridStep + 1) * gridStep; g < gridHiRaw; g += gridStep) {
        int yp = Y(vof((float)g));
        if (yp < 4 || yp > pb - 4 || (live && yp - y < 16 && y - yp < 16)) continue;
        axis_label(g, gridShow, PR + 6, yp - 3);
    }
    if (!live) return;
    bool up = fc >= fo;
    int xs = X(kq) + 4; if (xs < 0) xs = 0;
    if (xs < PR) hline_dash(xs, PR, y, up ? C_LIVEG : C_LIVEL, 2, 3, 0);
    int yt = y < 8 ? 8 : y > pb ? pb : y;
    rr(PR + 2, yt - 8, 320 - PR - 3, 17, 5, up ? C_GAIN : C_BEAR);
    long raw = raw_of(fc);
    uint8_t ts = (raw < 1000L * P10[W.dec] && gridShow < W.dec) ? (uint8_t)(gridShow + 1) : gridShow;
    text_on(price_raw(raw, ts), PR + 6, yt - 3, C_INK, 1, up ? C_GAIN : C_BEAR);
}

/* The app's floor: volume bars under the candles, the hours along the bottom, the market and timeframe at its right */
#define VOL_FLOOR 224
#define VOL_H 26
static void draw_volume(void) {
    int first = kf - VIS; if (first < 0) first = 0;
    int most = 1;
    for (int i = first; i < kf; i++) { int v = RD16(W.vol, i); if (v > most) most = v; }
    for (int i = first; i < kf; i++) {
        int x = XI(i); if (x < -BODY || x > PR) continue;
        int h = (int)((long)RD16(W.vol, i) * VOL_H / most); if (h < 1) h = 1;
        gfx_SetColor(BC(i) >= BO(i) ? I_VOLU : I_VOLD);
        gfx_FillRectangle(x - BODY / 2, VOL_FLOOR - h, BODY, h);
    }
}
static void draw_time_row(void) {
    int first = kf - VIS; if (first < 1) first = 1;
    int wt = textw(W.sym, 1) + 5 + textw("5M", 1), xt = PR - 6 - wt;   /* LINK 5M, right */
    for (int i = firstHourBar(first); i <= kf + 12 && i < nbars; i += 12) {
        uint32_t t = W.start + (uint32_t)i * 300;
        int x = XI(i);
        uint32_t day = t % 86400; char s[8];
        if (day == 0) { int m, d; civil(t, &m, &d); strcpy(s, MON[m - 1]); }
        else { int hh = (int)(day / 3600); s[0] = '0' + (char)(hh / 10); s[1] = '0' + (char)(hh % 10); s[2] = ':'; s[3] = '0'; s[4] = '0'; s[5] = 0; }
        int w = textw(s, 1);
        if (x - w / 2 < 4 || x + w / 2 > xt - 8) continue;
        gfx_SetColor(C_BG); gfx_FillRectangle(x - w / 2 - 3, 225, w + 6, 13);   /* lines pass under the labels */
        text(s, x - w / 2, 228, C_MUTED, 1);
    }
    gfx_SetColor(C_BG); gfx_FillRectangle(xt - 4, 225, wt + 8, 13);
    text(W.sym, xt, 228, C_TEXT, 1); text("5M", xt + wt - textw("5M", 1), 228, C_MUTED, 1);
}

/* the ride tag: side and live P&L, riding just above (long) or below (short) the price; the change of side glides */
static float tagOff = -999;
static void draw_ride_tag(float dt) {
#ifdef NO_TAG
    return;
#endif
    if (!pos.on) { tagOff = -999; return; }
    uint8_t col = openPnl >= 0 ? C_BULL : C_BEAR;
    char side[16]; strcpy(side, pos.dir > 0 ? "LONG " : "SHORT ");
    { char *o = side + strlen(side); long lx10 = (long)(pos.notional * 10 / (mode == M_BLOWUP ? pos.bankAtOpen : -pos.liq));
      if (mode == M_BLOWUP) { o = digits(o, lx10 / 10, lx10 % 10, 1); } else o = digits(o, (lx10 + 5) / 10, 0, 0); *o++ = 'x'; *o = 0; }
    char val[28]; char *e = money_to(val, openPnl, true);
    if (danger > 0.25f) { /* the forced exit is in play: say how far it is */
        float lr = rawp(fc), pct = (lr - rawp(pos.liqv)) / lr * 100.0f * pos.dir;
        int t10 = (int)(pct * 10 + 0.5f);
        strcpy(e, " LIQ "); e += 5; e = digits(e, t10 / 10, t10 % 10, 1); *e++ = '%'; *e = 0;
    }
    int w1 = textw(side, 1) + 12, w2 = textw(val, 1) + 14, w = w1 + w2, h = 19;
    int yl = Y(fc), x = PR - 4 - w;
    float above = -(float)(h + 9), below = 9, want = pos.dir > 0 ? above : below;
    if (yl + (int)want < PT - 30 || yl + (int)want + h > pb - 4) want = want == above ? below : above;
    if (tagOff < -900) tagOff = want;
    tagOff += (want - tagOff) * (1 - exp_f(-dt * 16));
    int ty = yl + (int)tagOff;
    if (ty < PT - 2 && x < 142) ty = yl + 9; /* the P&L tile owns the top-left: go under the price instead */
    if (ty < 4) ty = 4;
    if (ty > pb - h - 2) ty = pb - h - 2;
    rr(x, ty, w, h, 5, col);
    rr(x + w1, ty + 2, w2 - 2, h - 4, 4, C_PLATE);
    txtBg = col; text_c(side, x + w1 / 2, ty + 6, C_INK, 1); txtBg = C_PLATE;
    text_c(val, x + w1 + (w2 - 2) / 2, ty + 6, col, 1); txtBg = C_BG;
}

static void draw_marks(void) {
    static const uint8_t MKD[NMK] = { D_MK0, D_MK1, D_MK2, D_MK3 };
    for (uint8_t n = 0; n < NMK; n++) {
        Mark *m = &marks[n];
        if (!m->on) continue;
        float age = (now_s - m->t0) / m->life;
        if (age >= 1) { m->on = false; continue; }
        float fade = age < 0.7f ? 1 : 1 - (age - 0.7f) / 0.3f;
        uint8_t d = MKD[n];
        if (m->kind == 0) { /* a level that just decided something: the line spreads from the price */
            int y = Y(m->v), xc = X(kq);
            float spread = age * 6; if (spread > 1) spread = 1;
            seta(d, m->col == C_BEAR ? RGB_BEAR : RGB_TEXT, 0.95f * fade);
            int a = xc - (int)((float)xc * spread), b = xc + (int)((float)(PR - xc) * spread);
            gfx_SetColor(d); gfx_HorizLine(a, y, b - a); if (age < 0.33f) gfx_HorizLine(a, y + 1, b - a);
            if (fade > 0.4f) {
                int w = textw(m->txt, 1) + 10;
                gfx_SetColor(m->col); gfx_FillRectangle(PR - 8 - w, y - 20, w, 13);
                text_on(m->txt, PR - 3 - w, y - 17, C_INK, 1, m->col);
            }
        } else if (m->kind == 3) { /* a setup the market just decided: a ring closing on it, and what happened */
            int x = X(m->q0), y = Y(m->v0); float pop = age * 5; if (pop > 1) pop = 1;
            seta(d, m->col == C_BEAR ? RGB_BEAR : RGB_TEXT, fade);
            gfx_SetColor(d); gfx_Circle(x, y, 6 + (int)((1 - pop) * 14));
            if (fade > 0.4f) {
                int w = textw(m->txt, 1) + 10, cx = x + 10; if (cx + w > PR - 2) cx = x - w - 10;
                gfx_SetColor(m->col); gfx_FillRectangle(cx, y - 18, w, 13);
                text_on(m->txt, cx + 5, y - 15, C_INK, 1, m->col);
            }
        } else if (m->kind == 2) { /* a burst: a ring that grows from its point and fades */
            int x = X(m->q0), y = Y(m->v0), r = 3 + (int)(age * 26);
            seta(d, m->col == C_BEAR ? RGB_BEAR : m->col == C_GAIN ? RGB_GAIN : m->col == C_ORANGE ? RGB_ORANGE : RGB_TEXT, 1 - age);
            gfx_SetColor(d); gfx_Circle(x, y, r); if (age < 0.5f) gfx_Circle(x, y, r + 1);
        } else { /* the move you left */
            float t = age * 4; if (t > 1) t = 1;
            int xa = X(m->q0), ya = Y(m->v0), xb = X(m->q1), yb = Y(m->v1);
            int xm = xa + (int)((float)(xb - xa) * t), ym = ya + (int)((float)(yb - ya) * t);
            seta(d, RGB_TEXT, 0.8f * fade);
            gfx_SetColor(d);
            int steps = (xm - xa) > 0 ? (xm - xa) : 1;
            for (int s = 0; s <= steps; s++) if ((s / 3) % 2 == 0) gfx_SetPixel(xa + s, ya + (ym - ya) * s / steps);
            if (t >= 1 && fade > 0.4f) {
                gfx_FillCircle(xb, yb, 2);
                int w = textw(m->txt, 1) + 10, cx = xb + 6; if (cx + w > PR - 2) cx = xb - w - 8;
                gfx_SetColor(C_OLDUP); gfx_FillRectangle(cx, yb - 6, w, 13);
                text_on(m->txt, cx + 5, yb - 3, C_INK, 1, C_OLDUP);
            }
        }
    }
}

/* ---- drawing: over the chart (no shake) ----------------------------------------------------------- */
/* the thumb's ring where the keyboard's press lands (the screen's middle), its halo once a ride is open */
static void draw_floaters(void) {
    for (uint8_t n = 0; n < 3; n++) {
        Floater *f = &flo[n];
        if (!f->on) continue;
        float t = 1 - f->life / f->max, pop = t / 0.12f; if (pop > 1) pop = 1;
        uint8_t sc = f->cash ? (f->big ? 4 : 3) : (f->big ? 3 : 2);
        if (f->big && pop < 0.6f) sc++;
        int w = textw(f->txt, sc);
        while (w > 300 && sc > 1) { sc--; w = textw(f->txt, sc); }
        int x = f->x - w; if (x < 10) x = 10;
        int y = f->y - (int)(t * 41) - 4 * sc;
        uint8_t d = D_FL0 + n;
        float a = f->life / 0.4f; if (a > 1) a = 1;
        seta(d, f->col == C_BEAR ? RGB_BEAR : f->col == C_ORANGE ? RGB_ORANGE : f->col == C_BULL ? RGB_BULL : f->col == C_MUTED ? RGB_MUTED : RGB_TEXT, a);
        if (a > 0.5f) text_o(f->txt, x, y, d, sc); else text(f->txt, x, y, d, sc);
    }
}

static void draw_count(void) {
    float t = (now_s - countT) / 0.76f;
    if (countN <= 0 || t >= 1) return;
    char s[2] = { (char)('0' + countN), 0 };
    seta(D_COUNT, countN <= 3 ? RGB_BEAR : RGB_TEXT, (1 - t) * 0.9f);
    float g = t * 3; if (g > 1) g = 1;
    uint8_t sc = (uint8_t)(8 - 3 * g + 0.5f);
    text_c(s, PR / 2, (PT + PB) / 2 - 4 * sc, D_COUNT, sc);
}

/* the HUD: the P&L tile (the open trade while there is one) with its tick meter; the mode and clock plate; the hint */
static float meterMin = -100, meterMax = 100;
static float niceBound(float v) {
    static const float S[] = { 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000, 100000 };
    long a = (long)v; if (a < 0) a = -a;
    for (uint8_t i = 0; i < 10; i++) if (S[i] >= (float)a) return S[i];
    return 100000;
}
static float stage_value(float open) {
    const Stage *st = &CAREER[stage];
    if (st->goal == G_READS) return reads;
    if (st->goal == G_POINTS) return points;
    if (st->goal == G_PEAK) { float b = bank + open; return peakBank > b ? peakBank : b; }
    return realized + open;
}
static uint8_t stars_for(float v) { uint8_t n = 0; for (int i = 0; i < 3; i++) if (v >= (float)CAREER[stage].stars[i]) n++; return n; }
static char *goal_text(char *o, long t) {
    const Stage *st = &CAREER[stage];
    if (st->goal == G_READS) { o = digits(o, t, 0, 0); strcpy(o, t == 1 ? " READ" : " READS"); return o + strlen(o); }
    if (st->goal == G_POINTS) { o = digits(o, t, 0, 0); strcpy(o, " PTS"); return o + 4; }
    if (st->goal == G_PEAK) { strcpy(o, "PEAK $"); return digits(o + 6, t, 0, 0); }
    return money_to(o, (float)t, false);
}
static void draw_bot_marks(void) {
    if (botI < 0 || !botRace) return;
    for (uint8_t i = 0; i < nbm; i++) {
        int b = bm[i].bar; if (b >= kf) continue;
        int x = XI(b); if (x < 0 || x >= PR) continue;
        if (bm[i].dir > 0) tri(x, Y(BL(b)) + 4, 3, 5, true, C_ORANGE);
        else if (bm[i].dir < 0) tri(x, Y(BH(b)) - 9, 3, 5, false, C_ORANGE);
        else { gfx_SetColor(C_ORANGE); gfx_FillRectangle(x - 1, Y(BH(b)) - 6, 3, 3); }
    }
}
static void draw_hud(float total, float timeLeft) {
    bool riding = pos.on;
    int kick = now_s - kickT < 0.14f ? -3 : 0;
    char d[24], big[24];
    /* the score plate, top left, as the app's: a side or P&L label, the big number, the round's total under a ride */
    const char *lab; uint8_t labC, bigC; const char *sub = NULL; char subT[24];
    if (mode == M_CALLIT) {
        lab = "POINTS"; labC = C_MUTED; bigC = C_TEXT; digits(big, (long)rollShown, 0, 0);
    } else {
        float value = riding ? openPnl : rollShown, net = riding ? openPnl : (mode == M_BLOWUP ? total - startBank : total);
        lab = riding ? (pos.dir > 0 ? "LONG" : "SHORT") : mode == M_BLOWUP ? "BANK" : "P&L";
        labC = riding ? (pos.dir > 0 ? C_GAIN : C_BEAR) : C_MUTED;
        if (mode == M_BLOWUP && !riding) { money_to(big, value, false); if (big[0] == '+') memmove(big, big + 1, strlen(big)); }
        else money_to(big, value, false);
        bigC = net < -0.5f ? C_BEAR : net > 0.5f ? C_BULL : C_TEXT;
        if (riding) { strcpy(subT, mode == M_BLOWUP ? "BANK " : "P&L "); char *q = subT + strlen(subT); money_to(q, total, false); if (mode == M_BLOWUP && *q == '+') memmove(q, q + 1, strlen(q)); sub = subT; }
    }
    int pw = textw(big, 3) + 20; if (pw < 104) pw = 104;
    if (sub && textw(sub, 1) + 20 > pw) pw = textw(sub, 1) + 20;
    int ph = sub ? 52 : 42, px = 4, py = 4 + kick;
    frame(px, py, pw, ph, 6, C_BORDER, C_CARD);
    text(lab, px + 9, py + 6, labC, 1);
    if (mode == M_CALLIT) for (uint8_t i = 0; i < 3; i++) { uint8_t c = i < lives ? C_BEAR : C_BORDER; int hx = px + 66 + i * 12, hy = py + 8; gfx_SetColor(c); gfx_FillCircle(hx - 2, hy, 2); gfx_FillCircle(hx + 2, hy, 2); tri(hx, hy + 1, 4, 4, false, c); }
    if (mode == M_SNIPER) for (uint8_t i = 0; i < 3; i++) { gfx_SetColor(i < bullets ? C_TEXT : C_BORDER); gfx_FillRectangle(px + pw - 30 + i * 7, py + 5, 4, 9); }
    text_o(big, px + 9, py + 18, bigC, 3);
    if (sub) text(sub, px + 9, py + 41, C_MUTED, 1);
    /* what the plate does not hold, under it: the streak, the combo, Blow-Up's leverage */
    int ly = py + ph + 5;
    if (botI >= 0 && !botRace) { text(BOT_NAME[botI], px + 4, ly, C_ORANGE, 1); ly += 11; }   /* who is trading */
    if (botI >= 0 && botRace) { /* the rival: its name, its side, its P&L, a plate like yours but smaller */
        float bt = bot_total(); char r[24]; money_to(r, bt, false);
        int rw = textw(BOT_NAME[botI], 1) + textw(r, 1) + (botDir ? 30 : 22);
        frame(px, ly - 3, rw, 15, 4, botLead < 0 ? C_ORANGE : C_BORDER, C_CARD);
        text(BOT_NAME[botI], px + 6, ly + 1, C_ORANGE, 1);
        int rx = px + 6 + textw(BOT_NAME[botI], 1) + 5;
        if (botDir) { mark(rx, ly + 2, botDir > 0, botDir > 0 ? C_GAIN : C_BEAR); rx += 10; }
        text(r, rx, ly + 1, bt < -0.5f ? C_BEAR : C_TEXT, 1);
        if (now_s - leadCallT < 1.6f) { /* who just took the lead */
            const char *c = leadCall > 0 ? "YOU LEAD" : "BOT LEADS"; int cw = textw(c, 1) + 10, cy = ly + 15;   /* under the rival, clear of the caption */
            int pop = now_s - leadCallT < 0.12f ? 2 : 0;
            rr(px, cy - 3 - pop, cw, 15, 3, leadCall > 0 ? C_TEXT : C_ORANGE);
            txtBg = leadCall > 0 ? C_TEXT : C_ORANGE; text(c, px + 5, cy + 1 - pop, C_INK, 1); txtBg = C_BG;
        }
        ly += 17;
    }
    if (mode == M_CALLIT && callStreak > 1) { d[0] = 'x'; char *o = digits(d + 1, callStreak, 0, 0); strcpy(o, " STREAK"); text(d, px + 4, ly, C_ORANGE, 1); }
    if (combo > 1) { d[0] = 'x'; char *o = digits(d + 1, combo, 0, 0); strcpy(o, " COMBO"); text(d, px + 4, ly, C_ORANGE, 1); }

    /* the mode and the clock, top right, as the app's pill; its orange line runs down with the time (Blow-Up: the
     * leverage, which only climbs) */
    {
        const char *mn = stage >= 0 ? "CAREER" : botI >= 0 ? "BOT" : MODE_NAME[mode];
        if (mode == M_BLOWUP) { long l10 = (long)(lev * 10); char *o = digits(d, l10 / 10, l10 % 10, 1); strcpy(o, "x"); }
        else { int sl = timeLeft > 0 ? (int)(timeLeft + 0.99f) : 0; d[0] = (char)('0' + sl / 60); d[1] = ':'; d[2] = (char)('0' + (sl % 60) / 10); d[3] = (char)('0' + sl % 10); d[4] = 0; }
        int wm = textw(mn, 1) + 18, wc = textw("0:00", 1) + 18, w = wm + wc, x = 316 - w, y = 4;
        frame(x, y, w, 21, 5, C_BORDER, C_CARD);
        gfx_SetColor(C_BORDER); gfx_VertLine(x + wm, y + 1, 19);
        text_c(mn, x + wm / 2, y + 7, C_TEXT, 1);
        bool low = mode != M_BLOWUP && timeLeft <= 15;
        if (low) seta(D_CLOCK, RGB_BEAR, 0.7f + 0.3f * sin_f(now_s * 6.2832f));
        text_c(d, x + wm + wc / 2, y + 7, low ? D_CLOCK : C_TEXT, 1);
        float frac = mode == M_BLOWUP ? lev / 20 : timeLeft / (stage >= 0 ? (float)CAREER[stage].secs : ROUND_SECS);
        if (frac < 0) frac = 0; if (frac > 1) frac = 1;
        gfx_SetColor(low ? D_CLOCK : C_ORANGE); gfx_FillRectangle(x + 4, y + 23, (int)((w - 8) * frac), 2);
    }
    if (stage >= 0 && (lockI < 0 || now_s - lockT > 2.6f)) { /* the stage's goal under the pill: stars so far and the next target */
        uint8_t got = stars_for(stage_value(riding ? openPnl : 0));
        char g[24]; strcpy(g, "STAGE "); digits(g + 6, stage + 1, 0, 0);
        text_r(g, 316, 32, C_MUTED, 1);
        for (int i = 0; i < 3; i++) star(284 + i * 12, 43, i < got ? C_ORANGE : C_BORDER);
        if (got < 3) { goal_text(g, CAREER[stage].stars[got]); text_r(g, 316, 55, C_TEXT, 1); }
    }
    /* the keys, until the first ride */
    if (introT <= 0 && !rode && mode != M_CALLIT && botI < 0) {
        bool sh = shorts();
        int w = textw(K_GO, 1) + (sh ? textw(" - " K_SHORT, 1) + 42 : 30), x = PR / 2 - w / 2, py = VOL_FLOOR - 36;
        frame(x, py, w, 16, 4, C_BORDER, C_CARD);
        text(K_GO, x + 10, py + 4, C_TEXT, 1);
        int a = x + 10 + textw(K_GO, 1) + 4;
        mark(a, py + 5, true, C_TEXT);
        if (sh) { text("- " K_SHORT, a + 11, py + 4, C_TEXT, 1); mark(a + 11 + textw("- " K_SHORT, 1) + 4, py + 5, false, C_TEXT); }
    }
    labTop = 999;
}

/* Run intro: the mode, then GO slams in, then its line draws */
#define INTRO_S 1.15f
static void draw_intro(void) {
    if (introT <= 0) return;
    float t = INTRO_S - introT, fade = introT < 0.25f ? introT / 0.25f : 1;
    float g = (t - 0.12f) / 0.45f;
    if (g > 0) {
        uint8_t sc = g < 0.35f ? 14 : g < 0.7f ? 7 : 8;
        seta(D_GO, RGB_ORANGE, fade);
        text_c("GO", PR / 2, 140 - 4 * sc, D_GO, sc);
    }
    float l = (t - 0.3f) / 0.6f; if (l > 1) l = 1;
    if (l > 0) {
        float e = 1 - (1 - l) * (1 - l) * (1 - l);
        int w = (int)(115 * e);
        gfx_SetColor(D_GO); gfx_FillRectangle(PR / 2 - w / 2, 176, w, 3);
    }
}

/* ---- keys and the self-test ---------------------------------------------------------------------- */
/* A self-test (appvar SRAUTO: shot id, market) scripts the keys by game time; ids 0-8 save one frame (SRSHA, run-length,
 * and the palette SRSHP) and quit, so a USB host can see the game running; id 9 only plays the script. */
static uint8_t K1, K6, K7, P1, P6, P7;
static int8_t autoshot = -1;
static uint8_t scene, frames;
static bool quit_now;
static int8_t forcePreset = -1;
static const float shotAt[] = { 0, 0, 8.12f, 11.0f, 14.15f, 23.5f, 37.3f, 56.25f, 0 };
static void scan(void) {
    kb_Scan(); K1 = kb_Data[1]; K6 = kb_Data[6]; K7 = kb_Data[7];
    if (autoshot < 0) return;
    K1 = 0; K7 = 0; K6 &= kb_Clear;
    if (scene == 0 && frames >= 2 && autoshot != 0) K6 |= kb_Enter;
    if (scene == 1 && introT <= 0) {
        float e = elapsed;
        if ((e >= 4.0f && e < 4.06f) || (e >= 5.0f && e < 5.06f)) K1 |= kb_2nd;  /* taps push the tape */
        if (e >= 8.0f && e < 14.0f) K1 |= kb_2nd;                                 /* a long */
        if (e >= 20.0f && e < 26.0f) K7 |= kb_Down;                               /* a short */
        if (e >= 31.0f && e < 41.0f) K1 |= kb_2nd;                                /* a long, slid short */
        if (e >= 37.0f && e < 41.0f) K7 |= kb_Down;
        if (e >= 46.0f) K7 |= kb_Up;                                              /* held into the bell */
    }
}
static bool pressed(uint8_t grp, uint8_t mask) {
    uint8_t kk = grp == 7 ? K7 : grp == 6 ? K6 : K1, p = grp == 7 ? P7 : grp == 6 ? P6 : P1;
    return (kk & mask) && !(p & mask);
}
static void latch(void) { P7 = K7; P6 = K6; P1 = K1; }
static void present(void) {
    if (autoshot >= 0 && autoshot <= 8 && !quit_now) {
        bool shot = (autoshot == 0 && scene == 0 && frames >= 2) || (autoshot == 8 && scene == 2 && frames >= 2) ||
                    (scene == 1 && autoshot == 1 && introT > 0 && introT < 0.62f) ||
                    (scene == 1 && autoshot >= 2 && autoshot <= 7 && introT <= 0 && elapsed >= shotAt[autoshot]);
        if (shot) {
            /* run-length pairs (value, count), so a frame fits in the RAM a running program leaves */
            static uint8_t rle[512];
            const uint8_t *draw = (*(uint8_t **)0xE30014 == gfx_vram) ? gfx_vram + 76800 : gfx_vram;
            ti_var_t v = ti_Open("SRSHA", "w");
            if (v) {
                uint24_t n = 0, i = 0, total = 0;
                while (i < 76800 && total < 50000) {
                    uint8_t c = draw[i]; uint8_t run = 1;
                    while (i + run < 76800 && run < 255 && draw[i + run] == c) run++;
                    rle[n++] = c; rle[n++] = run; i += run;
                    if (n == sizeof rle) { if (ti_Write(rle, n, 1, v) != 1) break; total += n; n = 0; }
                }
                if (n) ti_Write(rle, n, 1, v);
                ti_Close(v);
            }
            v = ti_Open("SRSHP", "w"); if (v) { ti_Write((const void *)gfx_palette, 512, 1, v); ti_Close(v); }
            quit_now = true;
        }
    }
    frames++;
    gfx_SwapDraw();
}

