/* activityXp: a finished run of 15 s or more with a decision in it */
static long run_xp(void) {
    int trades = rides > 8 ? 8 : rides, att = callsN > 8 ? 8 : callsN;
    if (elapsed < 15 || !(trades || att)) return 0;
    int w = wins > trades ? trades : wins, rd = reads;
    float act = elapsed > 90 ? 90 : elapsed;
    float x = 60 + (trades ? trades : att) * 8 + w * 12 + rd * 18 + (float)(int)(act / 3 + 0.5f);
    float mult = (mode == M_RUSH || mode == M_CALLIT) ? 1 : 1.25f;
    if (stage >= 0) mult *= 1.2f;
    x *= mult;
    if (plays < 3) x *= 1.5f; /* first 3 runs */
    return (long)(x + 0.5f);
}

/* ---- daily missions (core.js MISSIONS, missionsToday): three a UTC day, the same three for everyone ---- */
enum { MS_READS, MS_PROFIT, MS_COMBO, MS_SHORTS, MS_CALLS, MS_BANK, MS_CLEAN, MS_PLAYS, MS_VARIETY, MS_STAR, MS_SKIPS, MS_DAILY, MS_COMEBACK, NMISSION };
static const struct { const char *t; long goal; bool sum; } MISSIONS[NMISSION] = {
    { "WIN 5 PATTERN TRADES", 5, true }, { "+$750 TIMED RUN", 750, false }, { "HIT A x3 COMBO", 3, false },
    { "WIN 3 SHORT TRADES", 3, true }, { "6 RIGHT - CALL IT", 6, false }, { "BLOW-UP BANK $20K", 20000, false },
    { "GREEN PRO - 0 LIQUIDATIONS", 1, true }, { "PLAY 4 RUNS", 4, true }, { "WIN 3 PATTERNS - 1 RUN", 3, false },
    { "NEW CAREER STAR", 1, true }, { "SKIP 4 LOSERS - RUSH", 4, true }, { "TODAY'S FREE RUN", 1, true }, { "COMEBACK: -$250 TO GREEN", 1, true },
};
static uint24_t msDay; static uint8_t msIds[3], msDone, msBonus; static long msProg[3];
static unsigned long mb_a;
static unsigned long mulberry(void) {
    mb_a += 0x6D2B79F5UL;
    unsigned long t = (mb_a ^ (mb_a >> 15)) * (1 | mb_a);
    t = (t + ((t ^ (t >> 7)) * (61 | t))) ^ t;
    return t ^ (t >> 14);
}
static void missions_today(uint24_t d) {
    if (msDay == d && msDay) return;
    /* hashSeed('missions:YYYY-MM-DD') */
    char key[24]; strcpy(key, "missions:");
    { long z = (long)d + 719468, era = z / 146097, doe = z - era * 146097, yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
      long y = yoe + era * 400, doy = doe - (365 * yoe + yoe / 4 - yoe / 100), mp = (5 * doy + 2) / 153, dd = doy - (153 * mp + 2) / 5 + 1, m = mp < 10 ? mp + 3 : mp - 9;
      if (m <= 2) y++;
      char *o = key + 9; { char t[12]; int n = u2s(t, (unsigned long)y); memcpy(o, t, n); o += n; }
      *o++ = '-'; *o++ = (char)('0' + m / 10); *o++ = (char)('0' + m % 10); *o++ = '-'; *o++ = (char)('0' + dd / 10); *o++ = (char)('0' + dd % 10); *o = 0; }
    unsigned long h = 2166136261UL;
    for (const char *c = key; *c; c++) { h ^= (unsigned char)*c; h *= 16777619UL; }
    mb_a = h % 1000000000UL + 1;
    uint8_t pool[NMISSION], n = NMISSION;
    for (uint8_t i = 0; i < NMISSION; i++) pool[i] = i;
    for (uint8_t j = 0; j < 3; j++) {
        unsigned long r = mulberry(); uint8_t pick = (uint8_t)(((unsigned long long)r * n) >> 32);
        msIds[j] = pool[pick]; for (uint8_t q = pick; q + 1 < n; q++) pool[q] = pool[q + 1]; n--;
    }
    msDay = d; msDone = 0; msBonus = 0; msProg[0] = msProg[1] = msProg[2] = 0;
}
static uint8_t popcount(unsigned long x) { uint8_t n = 0; while (x) { n += (uint8_t)(x & 1); x >>= 1; } return n; }
static uint8_t msJust; /* bit per mission finished by the run just played, bit 3 the all-three bonus */
static long progress_missions(uint8_t newStars, bool todayDaily) {
    missions_today(today());
    long v[NMISSION] = { 0 };
    v[MS_READS] = reads; v[MS_PROFIT] = mode != M_BLOWUP && mode != M_CALLIT ? (long)realized : 0; v[MS_COMBO] = bestCombo;
    v[MS_SHORTS] = shortWins; v[MS_CALLS] = callsRight; v[MS_BANK] = mode == M_BLOWUP ? (long)peakBank : 0;
    v[MS_CLEAN] = mode == M_PRO && stage < 0 && realized > 0 && !liqs; v[MS_PLAYS] = 1; v[MS_VARIETY] = popcount(wonKinds);
    v[MS_STAR] = newStars; v[MS_SKIPS] = goodSkips; v[MS_DAILY] = todayDaily; v[MS_COMEBACK] = comebacks;
    long pay = 0; msJust = 0;
    for (uint8_t i = 0; i < 3; i++) {
        uint8_t id = msIds[i];
        if (msDone & (1 << i)) continue;
        msProg[i] = MISSIONS[id].sum ? msProg[i] + v[id] : (v[id] > msProg[i] ? v[id] : msProg[i]);
        if (msProg[i] >= MISSIONS[id].goal) { msDone |= (uint8_t)(1 << i); msJust |= (uint8_t)(1 << i); pay += 60; }
    }
    if (!msBonus && msDone == 7) { msBonus = 1; msJust |= 8; pay += 120; }
    return pay;
}

/* SRSAVE: 'S2', plays, a best per mode (and which are set), the day of the last Free run and its best */
static float bestM[NMODES]; static uint8_t hasM; static uint24_t dailyDay; static bool dailyPlayed;
static void load_save(void) {
    ti_var_t v = ti_Open("SRSAVE", "r");
    if (!v) return;
    char tag[2] = { 0, 0 };
    if (ti_GetSize(v) >= 2 + 1 + 4 * NMODES + 1 + 3 && ti_Read(tag, 1, 2, v) == 2 && tag[0] == 'S' && tag[1] >= '2' && tag[1] <= '7') {
        ti_Read(&plays, 1, 1, v); ti_Read(bestM, sizeof bestM, 1, v); ti_Read(&hasM, 1, 1, v); ti_Read(&dailyDay, 3, 1, v);
        if (tag[1] >= '3') ti_Read(starsOf, 1, NSTAGE, v);
        if (tag[1] >= '5') { ti_Read(&msDay, 3, 1, v); ti_Read(msIds, 1, 3, v); ti_Read(&msDone, 1, 1, v); ti_Read(&msBonus, 1, 1, v); ti_Read(msProg, 4, 3, v); }
        if (tag[1] >= '4') { ti_Read(&xp, 4, 1, v); ti_Read(&cash, 4, 1, v); ti_Read(&owned, 2, 1, v); ti_Read(&themeI, 1, 1, v); if (themeI >= NTHEME) themeI = 0; owned |= 3; }
        if (tag[1] >= '6') ti_Read(&botBeat, 1, 1, v);
        if (tag[1] >= '7') { ti_Read(&chartStyle, 1, 1, v); if (chartStyle >= NSTYLE) chartStyle = 0; }
    } else { ti_Rewind(v); if (ti_GetSize(v) >= 4) { ti_Read(&bestM[M_PRO], 4, 1, v); hasM = 1 << M_PRO; } if (ti_GetSize(v) >= 5) ti_Read(&plays, 1, 1, v); }
    ti_Close(v);
}
static void save_save(void) {
    ti_var_t v = ti_Open("SRSAVE", "w");
    if (!v) return;
    ti_Write("S7", 1, 2, v); ti_Write(&plays, 1, 1, v); ti_Write(bestM, sizeof bestM, 1, v); ti_Write(&hasM, 1, 1, v); ti_Write(&dailyDay, 3, 1, v);
    ti_Write(starsOf, 1, NSTAGE, v);
    ti_Write(&msDay, 3, 1, v); ti_Write(msIds, 1, 3, v); ti_Write(&msDone, 1, 1, v); ti_Write(&msBonus, 1, 1, v); ti_Write(msProg, 4, 3, v);
    ti_Write(&xp, 4, 1, v); ti_Write(&cash, 4, 1, v); ti_Write(&owned, 2, 1, v); ti_Write(&themeI, 1, 1, v); ti_Write(&botBeat, 1, 1, v); ti_Write(&chartStyle, 1, 1, v);
    ti_Close(v);
}

